import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`hotel-revenue-forecast`,heroTitle:`Forecast your hotel revenue in minutes`,heroSubtitle:`Perplexity Computer analyzes your property, models demand and pricing trends, and builds a revenue forecast — automatically.`,inputUrlCta:`Forecast my revenue`,inputUrlPlaceholder:`yourhotel.com`,inputUrlPrefill:`Go to {url} and perform a comprehensive hotel revenue analysis. 1) Extract the property details — room types, room count, location, star rating, amenities, and pricing tiers. 2) Research local market conditions — competing hotels, seasonal demand patterns, local events, and tourism trends for the area. 3) Analyze publicly available occupancy and ADR benchmarks for comparable properties in the market. 4) Build a 12-month revenue forecast broken down by month, including projected occupancy rates, average daily rate (ADR), RevPAR, and total room revenue. 5) Identify the top 5 revenue optimization opportunities — pricing adjustments, high-demand periods to capitalize on, low-occupancy windows to target with promotions, and channel mix recommendations. 6) Deliver everything in a clear dashboard format with monthly projections, seasonal trends, competitor rate comparisons, and a prioritized action plan to maximize revenue.`,heroOverlaySteps:[`Analyzing your property details, room types, and pricing`,`Researching local market demand, competitors, and seasonal trends`,`Modeling occupancy, ADR, and RevPAR projections month by month`,`12-month revenue forecast and optimization plan — ready to review`],generatingSteps:[`Visiting {url} to extract property details, room types, and current pricing`,`Designing an agent to research market demand, competitor rates, and seasonal patterns`,`Configuring 12-month revenue projections with occupancy, ADR, and RevPAR modeling`,`Setting up your revenue optimization playbook with prioritized actions`],featureSectionTitle:`From property URL to revenue forecast`,featureCardTitles:[`Connects to your hospitality stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Analytics, Notion, Slack, QuickBooks — Computer feeds forecasts and rate recommendations into the tools your revenue team already uses.`,`12-month revenue projections. Occupancy and ADR forecasts by month. Competitor rate benchmarks. Seasonal demand maps. A prioritized plan to maximize RevPAR.`],capabilitySectionTitle:`Your revenue manager, on autopilot`,capabilitySectionSubtitle:`Paste your hotel URL, step away, come back to a complete revenue forecast.`,capabilityCards:[{title:`Property Analysis`,description:`Computer can extract your room types, pricing tiers, amenities, and positioning — and benchmark them against comparable properties in your market.`},{title:`Demand Modeling`,description:`Computer can research seasonal patterns, local events, and tourism trends — and project occupancy rates for every month of the year.`},{title:`Rate Optimization`,description:`Computer can analyze competitor pricing and demand signals — and recommend ADR adjustments to maximize revenue across peak and off-peak periods.`},{title:`Connect Your Tools`,description:`Computer can push forecasts to Google Sheets, sync insights to Notion, and send alerts to Slack — build workflows across your entire revenue stack.`},{title:`Remember & Learn`,description:`Computer can remember your property data, past forecasts, and actual performance — so every projection gets more accurate over time.`},{title:`Monitor & Alert`,description:`Computer can track competitor rate changes and demand shifts weekly — and flag when you should adjust pricing or launch a promotion.`}]});export{t as default};
